var RN={R1:"Round 1",R2:"Round 2",Open:"Open round"};
function sShort(s){return s.slice(0,3)+" ’"+s.slice(-2);}
function cats(){var c={UR:1,OCS:1};c[ST.cat]=1;if(ST.ip)c.IP=1;if(ST.inst)c.INST=1;return c;}
function chances(o){o=o||{};var co=o.co!=null?o.co:ST.course,one=o.i!=null,D=ST.data,C=cats(),g={},rank=parseInt(ST.rank,10)||0;
 D.rows.forEach(function(r){if(r[2]!==co||(one&&r[3]!==o.i)||!C[r[5]])return;if(r[6]&&!ST.pw)return;var k=r[3]+"|"+r[4];var x=g[k]||(g[k]={i:r[3],b:r[4],s:{},rows:[]});x.rows.push(r);if(!(r[0] in x.s)||r[8]>x.s[r[0]])x.s[r[0]]=r[8];});
 var out=[];Object.keys(g).forEach(function(k){var x=g[k];if(!one&&ST.mb!==""&&x.b!==+ST.mb)return;var ss=Object.keys(x.s).map(Number).sort(function(a,b){return b-a;});x.ss=ss;var rec=ss.slice(0,4).map(function(s){return x.s[s];});
  x.last=x.s[ss[0]];x.mx=Math.max.apply(null,rec);
  // like the NEET predictor: expected closing = recent sessions weighted to the newest (log scale), spread from how much it moved
  var wS=0,lS=0,ls=rec.map(function(c){return Math.log(c);});ls.forEach(function(l,j){var w=[4,2.5,1.5,1][j];wS+=w;lS+=w*l;});var mu=lS/wS,v=0;ls.forEach(function(l,j){var w=[4,2.5,1.5,1][j];v+=w*(l-mu)*(l-mu);});
  var sg=Math.max(rec.length>1?0.2:0.3,Math.min(0.6,Math.sqrt(v/wS)*1.1+0.08));x.exp=Math.round(Math.exp(mu));
  if(rank){var pc=Math.round(100*phi((mu-Math.log(rank))/sg));x.pc=Math.max(1,Math.min(99,pc));if(x.pc<5&&ST.mb===""&&!one&&!o.all)return;x.ch=x.pc>=80?"s":x.pc>=55?"l":x.pc>=30?"m":x.pc>=5?"x":"u";}
  out.push(x);});
 out.sort(function(a,b){return rank?((b.pc>=80)-(a.pc>=80))||(a.pc>=80?a.exp-b.exp:b.pc-a.pc||b.exp-a.exp):(a.last-b.last);});return out;}
function phi(z){var t=1/(1+0.3275911*Math.abs(z/Math.SQRT2)),y=1-((((1.061405429*t-1.453152027)*t+1.421413741)*t-0.284496736)*t+0.254829592)*t*Math.exp(-z*z/2);return 0.5*(1+(z>=0?y:-y));}
var CH={s:["Safe","s"],l:["Likely","l"],m:["Borderline","m"],x:["Stretch","x"],u:["Unlikely","x"]};
