  '<div class="ini-sum">'+(rank?"Your chance at rank <b>"+num(rank)+"</b> ("+esc(({UR:"General"})[ST.cat]||ST.cat)+(ST.pw?", PwBD":"")+") for every branch here. Tap a branch for every round.":"Add your rank in My chances to see your % for each branch. Tap a branch for every round.")+"</div>"+
  (secs||'<div class="ini-empty">No seats for your category here in recent sessions.</div>')+
  '<h5>About '+esc(D.iname[i])+"</h5>"+instFacts(i)+(x.reservation?'<div class="ini-facts"><div><b>Reservation:</b> '+esc(x.reservation)+"</div></div>":"")+(x.src?'<div class="ini-src">Source: '+esc(x.src)+"</div>":"")+"</div></div>";
 ov.addEventListener("click",function(e){if(e.target===ov||e.target.closest(".ini-x")){closeInst();return;}var r=e.target.closest(".ini-r");if(r&&!e.target.closest(".ini-d"))r.classList.toggle("open");});
